#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Runs on the laptop and drives the NAS over SSH. Secrets go from a hidden
# prompt straight into files on the NAS over SSH stdin: they are never written
# to the laptop's disk or put on a command line. Only non-secret settings are
# saved locally, in .nas-setup.env (gitignored), for re-runs and for
# scripts/deploy.sh.

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
NAS_REPO_DIR=/volume1/docker/skylight-mcp-nas
NAS_SECRETS_DIR=/volume1/docker/secrets/skylight
REPO_URL=https://github.com/ericmasiello/skylight-mcp-nas.git
NAS=""

# DSM's SSH server predates post-quantum key exchange, and OpenSSH 10.1+
# warns about that on every connection. Silence it where the client knows the
# option; older clients would reject it.
SSH_OPTS=()
command ssh -G -o WarnWeakCrypto=no localhost >/dev/null 2>&1 && SSH_OPTS+=(-o WarnWeakCrypto=no)
ssh() { command ssh ${SSH_OPTS[@]+"${SSH_OPTS[@]}"} "$@"; }

# Synology gives non-interactive SSH a short PATH; docker and Git Server's git
# live outside it.
NAS_PATH='PATH="$PATH:/usr/local/bin:/var/packages/Git/target/bin"'

# nas CMD runs CMD on the NAS without a terminal (no sudo).
nas() { ssh -o BatchMode=yes "$NAS" "$NAS_PATH; $1"; }

# remote_exists NAME: the secret file exists and is non-empty on the NAS.
remote_exists() { nas "test -s '$NAS_SECRETS_DIR/$1'"; }

# put_remote NAME: writes stdin to the secret file NAME on the NAS (mode 600).
put_remote() {
  nas "umask 077 && rm -f '$NAS_SECRETS_DIR/$1' && cat > '$NAS_SECRETS_DIR/$1'"
  printf '  %s✓ wrote%s %s on the NAS\n' "$GREEN" "$RESET" "$NAS_SECRETS_DIR/$1"
}

# keep_remote NAME "what": true when NAME already exists and the human keeps it.
keep_remote() {
  if remote_exists "$1"; then
    say "$2 is already on the NAS ($NAS_SECRETS_DIR/$1)."
    if confirm "Replace it?"; then return 1; fi
    note "kept the existing $1"
    return 0
  fi
  return 1
}

run_wizard() {

TOTAL_STAGES=8
ENV_FILE="$REPO_ROOT/.nas-setup.env"

banner "Skylight NAS setup"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "NAS address and SSH key login"
say "The wizard talks to the NAS over SSH. It needs key login so it can run"
say "commands without asking for your password each time (sudo still asks)."
note "Tip: in your router, reserve the NAS's IP address (DHCP reservation) so it never changes."
ask NAS_HOST "NAS address [192.168.4.49]:"
NAS_HOST="${NAS_HOST:-192.168.4.49}"
ask NAS_USER "DSM user [ericmasiello]:"
NAS_USER="${NAS_USER:-ericmasiello}"
write_env NAS_HOST "$NAS_HOST"
write_env NAS_USER "$NAS_USER"
NAS="$NAS_USER@$NAS_HOST"
if ! ssh -o BatchMode=yes -o ConnectTimeout=5 "$NAS" true 2>/dev/null; then
  warn "Key login to $NAS doesn't work yet. Let's set it up."
  step "DSM → Control Panel → User & Group → Advanced → User Home → tick 'Enable user home service' → Apply."
  step "DSM → Control Panel → Terminal & SNMP → 'Enable SSH service' is ticked (port 22)."
  pause "Press Enter when both are on."
  if [[ ! -f "$HOME/.ssh/id_ed25519.pub" ]]; then
    say "You have no ~/.ssh/id_ed25519 key yet; creating one (choose a passphrase or leave empty)."
    ssh-keygen -t ed25519 -f "$HOME/.ssh/id_ed25519"
  fi
  # One plain ssh call: installs the key and fixes permissions (sshd ignores
  # keys in a group-writable home), so there is exactly one password prompt.
  say "Copying your public key to the NAS. Enter your DSM password once when asked."
  ssh -o PreferredAuthentications=password,keyboard-interactive "$NAS" \
    'umask 077 && mkdir -p ~/.ssh && cat >> ~/.ssh/authorized_keys && chmod 755 ~ && chmod 700 ~/.ssh && chmod 600 ~/.ssh/authorized_keys' \
    < "$HOME/.ssh/id_ed25519.pub"
  ssh -o BatchMode=yes -o ConnectTimeout=5 "$NAS" true \
    || { warn "Key login still fails. Check the two DSM settings above and re-run."; exit 1; }
fi
printf '  %s✓%s key login to %s works\n' "$GREEN" "$RESET" "$NAS"
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Check the NAS"
say "Looking for DSM 7.2+, the docker shared folder, git and Container Manager."
nas 'grep -E "^(productversion|buildnumber)=" /etc.defaults/VERSION' | sed 's/^/    /'
missing=()
nas 'test -d /volume1/docker' || missing+=("the docker shared folder on Volume 1 (install Container Manager)")
nas 'command -v git >/dev/null' || missing+=("git: Package Center → install 'Git Server'")
nas 'command -v docker >/dev/null' \
  || missing+=("docker: Package Center → install 'Container Manager'")
if (( ${#missing[@]} )); then
  for m in "${missing[@]}"; do warn "missing $m"; done
  say "Install what's missing, then re-run this wizard."
  exit 1
fi
printf '  %s✓%s docker folder, git and docker found\n' "$GREEN" "$RESET"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Get the code onto the NAS"
if nas "test -d '$NAS_REPO_DIR/.git'"; then
  say "The repo is already at $NAS_REPO_DIR; fetching the latest tags."
  nas "cd '$NAS_REPO_DIR' && git fetch --quiet --tags --force origin"
else
  if ! nas "git ls-remote --quiet '$REPO_URL' >/dev/null 2>&1"; then
    warn "The NAS can't read $REPO_URL. The repo must be public; see the README."
    exit 1
  fi
  say "Cloning $REPO_URL into $NAS_REPO_DIR."
  nas "git clone --quiet '$REPO_URL' '$NAS_REPO_DIR'"
fi
nas "mkdir -p '$NAS_REPO_DIR/data' '$NAS_REPO_DIR/ts-state' '$NAS_REPO_DIR/auth-data' && mkdir -p '$NAS_SECRETS_DIR' && chmod 700 '$NAS_SECRETS_DIR'"
printf '  %s✓%s code and folders ready\n' "$GREEN" "$RESET"
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Tailscale: tailnet name, HTTPS and Funnel"
open_url "https://login.tailscale.com/admin/dns"
step "On the DNS page, make sure MagicDNS is enabled."
step "Under HTTPS Certificates, click Enable HTTPS (skip if already on)."
step "Copy the Tailnet name at the top of the page (looks like tail1234.ts.net)."
ask TAILNET "Tailnet name (e.g. tail1234.ts.net):"
TAILNET="${TAILNET#https://}"; TAILNET="${TAILNET%/}"
write_env TAILNET "$TAILNET"
open_url "https://login.tailscale.com/admin/acls/file"
step "In the policy file, look for a \"nodeAttrs\" entry granting \"funnel\"."
step "If there is none, paste this on a new line just before the file's last closing }:"
note '    "nodeAttrs": [{"target": ["autogroup:member"], "attr": ["funnel"]}],'
step "Click Save."
pause "Press Enter when MagicDNS, HTTPS and Funnel are set."

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Tailscale: auth key"
if ! keep_remote ts.env "The Tailscale auth key"; then
  open_url "https://login.tailscale.com/admin/settings/keys"
  step "Click 'Generate auth key…'. Leave Reusable OFF and Ephemeral OFF; add no tags."
  step "Click Generate, then copy the key (starts tskey-auth-)."
  ask_secret TS_AUTHKEY "Paste the auth key:"
  [[ "$TS_AUTHKEY" == tskey-* ]] || warn "that doesn't start with tskey-; double-check it"
  printf 'TS_AUTHKEY=%s\n' "$TS_AUTHKEY" | put_remote ts.env
  unset TS_AUTHKEY
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "GitHub OAuth app (the sign-in in front of the server)"
EXTERNAL_URL="https://skylight.$TAILNET"
if ! keep_remote proxy.env "The GitHub OAuth settings"; then
  open_url "https://github.com/settings/applications/new"
  step "Application name: Skylight NAS"
  step "Homepage URL: $EXTERNAL_URL"
  step "Redirect URI (older form: Authorization callback URL): $EXTERNAL_URL/.auth/github/callback"
  note "  Leave 'Allow wildcard matching' and 'Enable Device Flow' off."
  step "Click Register application, then copy the Client ID."
  ask GITHUB_CLIENT_ID "Client ID:"
  step "Click 'Generate a new client secret' and copy it."
  ask_secret GITHUB_CLIENT_SECRET "Client secret:"
  ask GITHUB_ALLOWED_USERS "Your GitHub username (the only account allowed in) [ericmasiello]:"
  GITHUB_ALLOWED_USERS="${GITHUB_ALLOWED_USERS:-ericmasiello}"
  write_env GITHUB_ALLOWED_USERS "$GITHUB_ALLOWED_USERS"
  printf 'EXTERNAL_URL=%s\nGITHUB_ALLOWED_USERS=%s\nGITHUB_CLIENT_ID=%s\nGITHUB_CLIENT_SECRET=%s\n' \
    "$EXTERNAL_URL" "$GITHUB_ALLOWED_USERS" "$GITHUB_CLIENT_ID" "$GITHUB_CLIENT_SECRET" | put_remote proxy.env
  unset GITHUB_CLIENT_SECRET
fi
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Skylight account and confirm secret"
if ! keep_remote skylight_email "The Skylight email"; then
  ask SKYLIGHT_EMAIL "Skylight account email:"
  printf '%s' "$SKYLIGHT_EMAIL" | put_remote skylight_email
fi
if ! keep_remote skylight_password "The Skylight password"; then
  ask_secret SKYLIGHT_PASSWORD "Skylight account password:"
  printf '%s' "$SKYLIGHT_PASSWORD" | put_remote skylight_password
  unset SKYLIGHT_PASSWORD
fi
if ! keep_remote mcp_confirm_secret "The confirm secret"; then
  say "Generating a random confirm secret (signs confirm-gate tokens)."
  openssl rand -hex 32 | tr -d '\n' | put_remote mcp_confirm_secret
fi
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "File ownership (needs sudo on the NAS)"
say "The Skylight container runs as uid 1000, so it must own its secret files and"
say "the data folder. Enter your DSM password when sudo asks."
ssh -t "$NAS" "sudo sh -c 'cd \"$NAS_SECRETS_DIR\" && chown 1000:1000 skylight_email skylight_password mcp_confirm_secret && chmod 400 skylight_email skylight_password mcp_confirm_secret && chown root:root proxy.env ts.env && chmod 400 proxy.env ts.env && chown 1000:1000 \"$NAS_REPO_DIR/data\"'"
printf '  %s✓%s ownership set\n' "$GREEN" "$RESET"
pause

finish
say "Next:"
step "Make sure the GitHub repo is public (the NAS clones it over plain HTTPS)."
step "Run scripts/release.sh to tag the first version and deploy it."
step "After the machine 'skylight' appears in Tailscale, open"
note "    https://login.tailscale.com/admin/machines → skylight → … → Disable key expiry."
step "Then follow 'First Skylight sign-in' in the README."
printf '\n'
}

run_wizard "$@"; exit
